#!/usr/bin/env bash
set -euo pipefail
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)";BUILD_ROOT="$PROJECT_ROOT/build/sm64-modern-boulder-generator";mkdir -p "$BUILD_ROOT/module-cache"
xcrun swiftc -parse-as-library -swift-version 6 -Xfrontend -strict-concurrency=complete -module-cache-path "$BUILD_ROOT/module-cache" "$PROJECT_ROOT/SM64Modern/BoulderGeneratorBehavior.swift" "$PROJECT_ROOT/tests/sm64_modern_boulder_generator_smoke.swift" -o "$BUILD_ROOT/smoke"
swift_output="$($BUILD_ROOT/smoke)";printf '%s\n' "$swift_output";xcrun clang -std=c11 "$PROJECT_ROOT/tests/sm64_modern_boulder_generator_contract.c" -o "$BUILD_ROOT/contract";c_output="$($BUILD_ROOT/contract)";printf '%s\n' "$c_output";s="$(printf '%s\n' "$swift_output"|sed -n 's/^boulderGeneratorFingerprint=//p')";c="$(printf '%s\n' "$c_output"|sed -n 's/^boulderGeneratorFingerprint=//p')";[[ -n "$s"&&"$s" == "$c" ]]||{ echo "boulder generator mismatch Swift=$s C=$c" >&2;exit 1;};printf '%s\n' 'Swift/C boulder generator contract matched'
